import 'dart:io';
import 'dart:ui' as ui;
import 'package:flutter/material.dart';
import 'package:flutter/rendering.dart';
import 'package:flutter/services.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:hive_flutter/hive_flutter.dart';
import 'package:flutter_app/services/keepsake_tree_store.dart';
import 'package:flutter_app/services/backup_service.dart';
import 'package:flutter_app/screens/keepsake_forest_screen.dart';
import 'package:flutter_app/widgets/keepsake_tree_art.dart';
import 'package:flutter_app/theme.dart';
void main(){
 TestWidgetsFlutterBinding.ensureInitialized();late Directory dir;late Box box;late DateTime now;late bool premium;late KeepsakeTreeStore store;
 setUp(()async{dir=await Directory.systemTemp.createTemp('keepsake-test-');Hive.init(dir.path);box=await Hive.openBox('trees');now=DateTime.utc(2026,10,29,4);premium=true;store=KeepsakeTreeStore(open:()async=>box,now:()=>now,premium:()async=>premium);});
 tearDown(()async{await Hive.close();await dir.delete(recursive:true);});
 Future<KeepsakeTree> plant() =>store.plant(name:'엄마와의 봄날',kind:KeepsakeKind.love,metal:KeepsakeMetal.gold,day:'1999-04-03',text:'함께 걸었던 봄날을 기억하며.');
 test('old anniversary always starts at seed; persists across store reopening',()async{final t=await plant();expect(t.stage,0);expect(t.plantedDay,'2026-10-29');expect(t.notes.single.day,'1999-04-03');final reopened=KeepsakeTreeStore(open:()async=>box);expect((await reopened.load()).single.toJson(),t.toJson());});
 test('concurrent watering counts one Korean day, stage thresholds and rest preserve growth',()async{var t=await plant();await Future.wait([store.change(t,care:true),store.change(t,care:true)]);t=(await store.load()).single;expect(t.careDays.length,1);for(var i=1;i<30;i++){now=now.add(const Duration(days:1));t=await store.change(t,care:true);if(i==2)expect(t.stage,1);if(i==6)expect(t.stage,2);if(i==13)expect(t.stage,3);}expect(t.stage,4);now=now.add(const Duration(days:200));expect((await store.load()).single.stage,4);});
 test('Korean midnight, clock rollback and future anniversary do not grant growth',()async{now=DateTime.utc(2026,10,29,14,59);var t=await plant();t=await store.change(t,care:true);now=now.add(const Duration(minutes:2));t=await store.change(t,care:true);expect(t.careDays,['2026-10-29','2026-10-30']);now=now.subtract(const Duration(days:2));t=await store.change(t,care:true);expect(t.careDays.length,2);});
 test('edit date/content/metal preserves care, stale edit cannot overwrite or resurrect',()async{var t=await plant();final stale=t;t=await store.change(t,care:true);await expectLater(store.change(stale,name:'옛 수정'),throwsStateError);t=await store.change(t,metal:KeepsakeMetal.silver,notes:[KeepsakeNote(id:t.notes.first.id,day:'2030-01-01',text:'새 약속')]);expect(t.careDays.length,1);expect(t.stage,0);await store.remove(t);expect(await store.load(),isEmpty);await expectLater(store.change(t,name:'복원 불가'),throwsStateError);});
 test('free retains read/edit/delete but cannot plant or grow; entitlement is rechecked',()async{var t=await plant();premium=false;await expectLater(plant(),throwsStateError);await expectLater(store.change(t,care:true),throwsStateError);expect((await store.load()).single.id,t.id);t=await store.change(t,name:'보관하는 추억');await store.remove(t);expect(await store.load(),isEmpty);});
 test('bad dates/empty content/duplicate notes are rejected without storage changes',()async{await expectLater(store.plant(name:'나무',kind:KeepsakeKind.peace,metal:KeepsakeMetal.silver,day:'2026-02-30',text:'기억'),throwsFormatException);expect(await store.load(),isEmpty);final t=await plant();await expectLater(store.change(t,notes:[]),throwsFormatException);await expectLater(store.change(t,notes:[t.notes.first,t.notes.first]),throwsFormatException);expect((await store.load()).single.notes.length,1);});
 test('encrypted backup schema includes trees and rejects mismatched ids and bad growth',()async{final t=await plant();Map<String,dynamic> snapshot(Map raw)=>{'schema':1,'createdAt':now.toIso8601String(),'boxes':{'keepsake_trees':[{'key':t.id,'value':raw}]},'settings':<String,dynamic>{}};BackupService.validate(snapshot(t.toJson()));expect(()=>BackupService.validate(snapshot({...t.toJson(),'id':'wrong'})),throwsFormatException);expect(()=>BackupService.validate(snapshot({...t.toJson(),'careDays':['2026-10-28']})),throwsFormatException);});
 for(final size in [const Size(390,844),const Size(320,640)]){
 testWidgets('seed editor and personal memory tree fit $size and start with seed',(tester)async{
 tester.view.physicalSize=size;tester.view.devicePixelRatio=1;addTearDown(tester.view.resetPhysicalSize);addTearDown(tester.view.resetDevicePixelRatio);
 const dest=String.fromEnvironment('KEEPSAKE_CAPTURE_DIR');if(dest.isNotEmpty){for(final name in ['GowunDodum','GamjaFlower']){final font=FontLoader(name)..addFont(rootBundle.load('assets/fonts/$name-Regular.ttf'));await tester.runAsync(font.load);}final font=FontLoader('MaterialIcons')..addFont(rootBundle.load('fonts/MaterialIcons-Regular.otf'));await tester.runAsync(font.load);}
 await tester.runAsync(plant);final key=GlobalKey();await tester.pumpWidget(MaterialApp(debugShowCheckedModeBanner:false,theme:appTheme,builder:(c,w)=>MediaQuery(data:MediaQuery.of(c).copyWith(disableAnimations:true),child:w!),home:RepaintBoundary(key:key,child:KeepsakeForestScreen(store:store))));await tester.runAsync(()async{await Future<void>.delayed(const Duration(milliseconds:60));});await tester.pumpAndSettle();expect(find.text('엄마와의 봄날'),findsOneWidget);expect(tester.takeException(),isNull);
 if(size.width==390&&dest.isNotEmpty){await tester.runAsync(()async{final image=await (key.currentContext!.findRenderObject() as RenderRepaintBoundary).toImage(pixelRatio:2);final data=await image.toByteData(format:ui.ImageByteFormat.png);await File('$dest/Mindnyang-Memory-Seeds-v52.png').writeAsBytes(data!.buffer.asUint8List());image.dispose();});}
 await tester.tap(find.text('기억의 씨앗 심기'));await tester.pumpAndSettle();expect(find.text('평화의 씨앗'),findsOneWidget);await tester.tap(find.text('평화의 씨앗'));await tester.pumpAndSettle();expect(tester.takeException(),isNull);expect(find.byType(KeepsakeTreeArt),findsWidgets);
 });}
 testWidgets('gold silver rose growth preview',(tester)async{const dest=String.fromEnvironment('KEEPSAKE_CAPTURE_DIR');tester.view.physicalSize=const Size(1000,760);tester.view.devicePixelRatio=1;addTearDown(tester.view.resetPhysicalSize);addTearDown(tester.view.resetDevicePixelRatio);final key=GlobalKey();await tester.pumpWidget(MaterialApp(debugShowCheckedModeBanner:false,theme:appTheme,home:RepaintBoundary(key:key,child:Scaffold(backgroundColor:const Color(0xFFFFFAF2),body:Padding(padding:const EdgeInsets.all(24),child:Column(children:[const Text('기억의 씨앗이 빛나는 나무로',style:TextStyle(fontSize:32,fontWeight:FontWeight.bold)),const Text('내가 고른 날짜와 이야기를 담아, 하루 한 번 천천히'),Expanded(child:Row(children:[for(final m in KeepsakeMetal.values)Expanded(child:Column(children:[Expanded(child:KeepsakeTreeArt(kind:m==KeepsakeMetal.gold?KeepsakeKind.love:KeepsakeKind.peace,metal:m,stage:4,animate:false)),Text('${m.label} 보석나무',style:const TextStyle(fontSize:22))]))])),const SizedBox(height:20),SizedBox(height:170,child:Row(children:[for(var stage=0;stage<5;stage++)Expanded(child:Column(children:[Expanded(child:KeepsakeTreeArt(kind:KeepsakeKind.love,metal:KeepsakeMetal.gold,stage:stage,animate:false)),Text(['씨앗','3일 · 새싹','7일 · 어린 나무','14일 · 빛나는 나무','30일 · 보석나무'][stage])]))]))]))))));await tester.pumpAndSettle();expect(tester.takeException(),isNull);if(dest.isNotEmpty)await tester.runAsync(()async{final image=await (key.currentContext!.findRenderObject() as RenderRepaintBoundary).toImage(pixelRatio:1.5);final data=await image.toByteData(format:ui.ImageByteFormat.png);await File('$dest/Mindnyang-Memory-Trees-v52.png').writeAsBytes(data!.buffer.asUint8List());image.dispose();});});
}
